const itens = $input.all();

const linhas = itens.map(item => {
  const j = item.json;
  const dataHora = j['Data / Hora'] || '(sem data)';
  const telefone = j['Telefone'] || '(sem telefone)';
  const usuario = j['_usuarioBruto'] || '(vazio)';
  return `- ${dataHora} | Telefone: ${telefone} | Usuário bruto: ${usuario}`;
});

const corpo = `Foram encontradas ${itens.length} ligação(ões) com usuário não identificado nesta execução (não foram gravadas na planilha):\n\n${linhas.join('\n')}\n\nVerifique o VoxFree para identificar o SDR correspondente.`;

return [{ json: {
  assunto: `Ligações com usuário não identificado (${itens.length})`,
  corpo
} }];

const d = new Date();
const dd = String(d.getDate()).padStart(2, '0');
const mm = String(d.getMonth() + 1).padStart(2, '0');
const yyyy = d.getFullYear();
const data = `${dd}/${mm}/${yyyy}`;
return [{ json: { reservation: `${data} - ${data}` } }];

// Pega a ultima linha (mais recente) ja gravada na planilha,
// para o Processar CSV saber a partir de onde continuar.
const items = $input.all();
if (items.length === 0) {
  return [{ json: { ultimaDataHora: null } }];
}
const ultima = items[items.length - 1].json;
return [{ json: { ultimaDataHora: ultima['Data / Hora'] || null } }];

const resposta = $input.first().json;
const caminho = (resposta.body || resposta.data || '').trim();
const caminhoLimpo = caminho.replace(/^\.\.\//, '');

const partes = caminhoLimpo.split('/');
const arquivo = partes.pop();
const diretorio = partes.join('/');

const urlCSV = 'https://app.voxfree.com.br/' + diretorio + '/' + encodeURIComponent(arquivo);

return [{ json: { csvUrl: urlCSV } }];

const item = $input.first().json;
const headers = item.headers || {};
const setCookie = headers['set-cookie'] || [];
const first = Array.isArray(setCookie) ? setCookie[0] : (setCookie || '');
const match = first.match(/ci_session=([^;]+)/);
if (!match) throw new Error('Cookie não encontrado');
return [{ json: { cookie: 'ci_session=' + match[1] } }];

const csvTexto = $input.first().json.data || $input.first().json.body || '';
const ultimaDataHora = $('Pegar Data da Última Ligação Salva').first().json.ultimaDataHora;

const delimitador = csvTexto.includes(';') ? ';' : ',';
const linhas = csvTexto.split('\n').filter(l => l.trim() !== '');
if (linhas.length < 2) return [];

const cabecalho = linhas[0].split(delimitador).map(c => c.trim());
const idxDuracao  = cabecalho.findIndex(c => c.toLowerCase().includes('dura'));
const idxDataHora = cabecalho.findIndex(c => c.toLowerCase().includes('data'));
const idxUsuario  = cabecalho.findIndex(c => c.toLowerCase().includes('usu'));

function toSegundos(dur) {
  const p = (dur || '').trim().split(':');
  if (p.length !== 3) return 0;
  return parseInt(p[0]) * 3600 + parseInt(p[1]) * 60 + parseInt(p[2]);
}

// Converte "DD/MM/AAAA HH:MM:SS" em timestamp comparavel
function paraTimestamp(dataHora) {
  const partes = (dataHora || '').trim().split(' ');
  if (partes.length < 2) return 0;
  const [dd, mm, yyyy] = partes[0].split('/').map(Number);
  const [h, m, s] = partes[1].split(':').map(Number);
  return new Date(yyyy, mm - 1, dd, h, m, s || 0).getTime();
}

function nomeSDR(usuario) {
  const u = (usuario || '').trim();
  const m = u.match(/^vendas\s+\d+\s+(.+)$/i);
  if (m) return m[1].trim();
  return u;
}

// Detecta usuario sem identificacao real: campo vazio, "Vendas N" sem nome
// depois (ex: "Vendas 4" sozinho), ou "Usuario N" generico (ex: "Usuario 3003")
function usuarioInvalido(usuarioBruto) {
  const u = (usuarioBruto || '').trim();
  if (u === '') return true;
  if (/^vendas\s+\d+\s*$/i.test(u)) return true;
  if (/^usu[aá]rio\s+\d+\s*$/i.test(u)) return true;
  return false;
}

const limiteTimestamp = ultimaDataHora ? paraTimestamp(ultimaDataHora) : 0;

return linhas.slice(1).reduce((acc, linha) => {
  const colunas = linha.split(delimitador).map(c => c.trim());

  const dataHora = idxDataHora >= 0 ? (colunas[idxDataHora] || '') : '';
  const ts = paraTimestamp(dataHora);

  // So mantem ligacoes mais novas que a ultima ja gravada na planilha
  if (ts <= limiteTimestamp) return acc;

  const usuarioBruto = idxUsuario >= 0 ? (colunas[idxUsuario] || '') : '';

  const duracao  = idxDuracao >= 0 ? (colunas[idxDuracao] || '00:00:00') : '00:00:00';
  const atendida = toSegundos(duracao) >= 60 ? 'Sim' : 'Não';

  const obj = {};
  cabecalho.forEach((col, i) => { obj[col] = colunas[i] || ''; });

  obj['Atendida'] = atendida;

  if (usuarioInvalido(usuarioBruto)) {
    // Usuario nao identificado: nao vai pra planilha, so gera alerta por e-mail
    obj['_usuarioInvalido'] = true;
    obj['_usuarioBruto'] = usuarioBruto === '' ? '(vazio)' : usuarioBruto;
  } else if (idxUsuario >= 0) {
    obj[cabecalho[idxUsuario]] = nomeSDR(usuarioBruto);
  }

  acc.push({ json: obj });
  return acc;
}, []);

